const Avatar = ({ user, size = 'md', ring = false }) => {
  if (!user) return null;
  const cls = size === 'sm' ? 'avatar avatar-sm' : size === 'lg' ? 'avatar avatar-lg' : size === 'xl' ? 'avatar avatar-xl' : 'avatar';
  const ooo = isUserOOO(user.id);
  const dotSize = size === 'sm' ? 8 : size === 'lg' ? 14 : size === 'xl' ? 16 : 10;
  return (
    <span style={{ position: 'relative', display: 'inline-block' }}>
      <span className={`${cls} avatar-ring`} title={`${user.name} · ${user.roleTh || ''}${ooo ? ' · ออกจากออฟฟิศ' : ''}`} style={{ background: user.color || 'var(--brand-soft)', color: 'oklch(25% 0.05 60)', boxShadow: ring ? '0 0 0 2px var(--surface), 0 0 0 4px var(--brand)' : 'none' }}>
        {user.initials}
      </span>
      {ooo && (
        <span title="ไม่อยู่ออฟฟิศ" style={{ position: 'absolute', bottom: -1, right: -1, width: dotSize, height: dotSize, borderRadius: '50%', background: 'var(--amber)', border: '1.5px solid var(--surface)', display: 'inline-block' }} />
      )}
    </span>
  );
};

const AvatarStack = ({ users, max = 4, size = 'sm' }) => {
  const shown = users.slice(0, max);
  const remaining = users.length - max;
  return (
    <span className="avatar-stack">
      {shown.map((u, i) => <Avatar key={i} user={u} size={size} />)}
      {remaining > 0 && (
        <span className={size === 'sm' ? 'avatar avatar-sm' : 'avatar'} style={{ background: 'var(--surface-3)', color: 'var(--ink-3)' }}>+{remaining}</span>
      )}
    </span>
  );
};

const Modal = ({ open, onClose, title, children, footer, wide = false }) => {
  React.useEffect(() => {
    if (!open) return;
    const handler = (e) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [open, onClose]);
  if (!open) return null;
  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className={`modal ${wide ? 'modal-wide' : ''}`} onClick={(e) => e.stopPropagation()}>
        <div className="modal-head">
          <h3 className="modal-title">{title}</h3>
          <button className="btn btn-ghost btn-icon-only btn-sm" onClick={onClose}><Icon name="x" size={16} /></button>
        </div>
        <div className="modal-body">{children}</div>
        {footer && <div className="modal-foot">{footer}</div>}
      </div>
    </div>
  );
};

const fmtBaht = (n) => '฿' + (n || 0).toLocaleString('en-US', { minimumFractionDigits: 0 });
const fmtNum = (n) => (n || 0).toLocaleString('en-US');

const nowTh = () => { const d = new Date(); const p = (n) => String(n).padStart(2,'0'); return `${p(d.getDate())}/${p(d.getMonth()+1)}/${d.getFullYear()} ${p(d.getHours())}:${p(d.getMinutes())}`; };
const parseTh = (s) => { if (!s) return null; const m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/); if (!m) return null; return new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1])); };
// parseThDT: parse "DD/MM/YYYY HH:mm" รวมเวลา (parseTh ตัดเวลาทิ้ง → SLA รายชั่วโมงเพี้ยน)
const parseThDT = (s) => {
  if (!s) return null;
  const m = String(s).match(/^(\d{2})\/(\d{2})\/(\d{4})(?:\s+(\d{2}):(\d{2}))?/);
  if (!m) return null;
  return new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1]), Number(m[4] || 0), Number(m[5] || 0));
};
// 🐛FIX ID ชนกัน: เดิมใช้ length ของ array (+300/+400/+500 ฐานต่างกันแต่ทับซ้อน)
// → สร้างพร้อมกัน 2 เครื่อง หรือ clone กับ create สลับกัน ได้ ID ซ้ำ → merge ทับกัน = ข้อมูลหาย
// ตอนนี้: สแกน ID เดิมทั้งหมดของ prefix → เลขสูงสุด + 1
const mintReqId = (prefix, requests) => {
  let maxN = 299;
  (requests || []).forEach(r => {
    if (!r || !r.id) return;
    const m = String(r.id).match(new RegExp('^' + prefix + '-26-0*(\\d+)$'));
    if (m) { const n = parseInt(m[1], 10); if (!isNaN(n) && n > maxN) maxN = n; }
  });
  return `${prefix}-26-${String(maxN + 1).padStart(4, '0')}`;
};

