// ===== Snooze — ซ่อนคำขอจาก Inbox จนถึงวันที่กำหนด (per-user) =====
// Key: fd-snooze-<userId> → { reqId: ISO-timestamp-string }
const getSnoozeMap = (userId) => {
  try { return JSON.parse(localStorage.getItem('fd-snooze-' + userId)) || {}; }
  catch (e) { return {}; }
};
const setSnoozeMap = (userId, map) => {
  try { localStorage.setItem('fd-snooze-' + userId, JSON.stringify(map)); } catch (e) {}
  window.dispatchEvent(new CustomEvent('fd-snooze-changed', { detail: { userId } }));
};
const isSnoozedUntil = (userId, reqId) => {
  const m = getSnoozeMap(userId);
  const until = m[reqId];
  if (!until) return null;
  const d = new Date(until);
  if (d.getTime() <= Date.now()) {
    // expired → clean up
    delete m[reqId];
    setSnoozeMap(userId, m);
    return null;
  }
  return d;
};
const snoozeRequest = (userId, reqId, untilDate) => {
  const m = getSnoozeMap(userId);
  m[reqId] = untilDate.toISOString();
  setSnoozeMap(userId, m);
};
const unsnoozeRequest = (userId, reqId) => {
  const m = getSnoozeMap(userId);
  delete m[reqId];
  setSnoozeMap(userId, m);
};
const useSnoozeMap = (userId) => {
  const [map, setMap] = React.useState(() => getSnoozeMap(userId));
  React.useEffect(() => {
    const h = (e) => { if (e.detail?.userId === userId) setMap(getSnoozeMap(userId)); };
    window.addEventListener('fd-snooze-changed', h);
    return () => window.removeEventListener('fd-snooze-changed', h);
  }, [userId]);
  return map;
};

// ===== Smart due date — แนะนำตามประเภท =====
const suggestDueDate = (type) => {
  const days = { event: 21, expense: 7, purchase: 14, withdrawal: 3, borrow: 3, overtime: 1, leave: 7, general: 7, hire: 30 }[type] || 7;
  const d = new Date(); d.setDate(d.getDate() + days);
  const p = (n) => String(n).padStart(2, '0');
  return `${p(d.getDate())}/${p(d.getMonth() + 1)}/${d.getFullYear()}`;
};

