// approver helper — รองรับทั้ง step.userId (1 คน) และ step.userIds[] (หลายคน OR/role-any)
const canApproveStep = (step, userId) => {
  if (!step || !userId) return false;
  const ids = step.userIds || (step.userId ? [step.userId] : []);
  if (ids.includes(userId)) return true;
  // ===== OOO Auto-forward — ถ้าผู้อนุมัติคนใดคนหนึ่ง OOO และมอบหมายให้ userId นี้ → ให้สิทธิ์อนุมัติ
  for (const id of ids) {
    if (isUserOOO(id)) {
      const ooo = getOOO(id);
      if (ooo.delegate && ooo.delegate === userId) return true;
    }
  }
  return false;
};

// คืน list ของ approver ปัจจุบัน (รวม delegate ของคน OOO)
const effectiveApprovers = (step) => {
  if (!step) return [];
  const ids = step.userIds || (step.userId ? [step.userId] : []);
  const out = [];
  ids.forEach(id => {
    if (isUserOOO(id)) {
      const ooo = getOOO(id);
      if (ooo.delegate) out.push({ userId: ooo.delegate, viaOOO: id });
      else out.push({ userId: id });
    } else {
      out.push({ userId: id });
    }
  });
  return out;
};

